  if(s.answer){$('message').textContent=s.outcome==='wrong-target'?`You hit ${s.hitLabel}. The target was ${s.answer}.`:s.outcome==='miss'?`Missed the target: ${s.answer}.`:`Found ${s.answer}! +${s.points}`;void speak(nameLine(s.answer,s.answer.length===1?'letter':'word'),false,true,true);}else{$('message').textContent=line;if(!s.points||s.points===10)void speak(line);}render();await wait(s.answer?1600:1050);if(generation!==sceneEpoch)return;feedback=null;shotStart=performance.now();if(p.round.done){$('message').textContent=WORDS.done;await checkpoint('round-end');if(generation!==sceneEpoch)return;void speak(WORDS.done);}else if(!midBreakDone&&input.shot+1===breakAt){midBreakDone=true;await checkpoint('mid-round');if(generation!==sceneEpoch)return;shotStart=performance.now();announce();}else announce();
